def move_lesson_materials(apps, schema_editor):
    Lesson = apps.get_model('courses', 'Lesson')
    LessonMaterial = apps.get_model('courses', 'LessonMaterial')
    for lesson in Lesson.objects.exclude(download_url__isnull=True).exclude(download_url='').iterator():
        LessonMaterial.objects.create(
            lesson_id=lesson.pk,
            title=lesson.download_name or 'Material complementar',
            url=lesson.download_url,
        )


def restore_lesson_materials(apps, schema_editor):
    Lesson = apps.get_model('courses', 'Lesson')
    LessonMaterial = apps.get_model('courses', 'LessonMaterial')
    for material in LessonMaterial.objects.exclude(url='').order_by('order', 'id').iterator():
        Lesson.objects.filter(pk=material.lesson_id, download_url__isnull=True).update(
            download_url=material.url, download_name=material.title,
        )


